local ShieldBossMaker = {}
local PRODUCTS = {
    iron_shieldboss = { name = "Železni ščitni boss", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ščitni boss za ščite." },
    bronze_shieldboss = { name = "Bronast ščitni boss", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ščitni boss za ščite." },
    silver_shieldboss = { name = "Srebrn ščitni boss", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ščitni boss za ščite." },
    gilded_shieldboss = { name = "Pozlačen ščitni boss", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ščitni boss za ščite." },
    jewel_set_shieldboss = { name = "Draguljast ščitni boss", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ščitni boss za ščite." },
    royal_sovereign_shieldboss = { name = "Kraljevski suveren ščitni boss", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ščitni boss z biseri za krono." },
}
local BUILDINGS = {
    shieldboss_workshop = { name = "Shieldboss delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    shieldboss_house = { name = "Shieldboss hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_shieldboss_atelier = { name = "Mojstrski shieldboss atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_shieldboss_palace = { name = "Suverena shieldboss palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ShieldBossMaker.ironStock = 18; ShieldBossMaker.bronzeStock = 14; ShieldBossMaker.woodStock = 10; ShieldBossMaker.leatherStock = 8; ShieldBossMaker.silverStock = 8; ShieldBossMaker.goldStock = 6; ShieldBossMaker.jewelStock = 4; ShieldBossMaker.pearlStock = 4
ShieldBossMaker.productStock = {}; ShieldBossMaker.buildings = {}; ShieldBossMaker.maker = nil; ShieldBossMaker.activeMaking = {}; ShieldBossMaker.totalProducts = 0; ShieldBossMaker.dayTimer = 0
function ShieldBossMaker.init() ShieldBossMaker.ironStock=18; ShieldBossMaker.bronzeStock=14; ShieldBossMaker.woodStock=10; ShieldBossMaker.leatherStock=8; ShieldBossMaker.silverStock=8; ShieldBossMaker.goldStock=6; ShieldBossMaker.jewelStock=4; ShieldBossMaker.pearlStock=4; ShieldBossMaker.productStock={}; ShieldBossMaker.buildings={}; ShieldBossMaker.maker=nil; ShieldBossMaker.activeMaking={}; ShieldBossMaker.totalProducts=0; ShieldBossMaker.dayTimer=0; print("[ShieldBossMaker] Royal Shield Boss Maker System initialized (6 products, 4 buildings)") end
function ShieldBossMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ShieldBossMaker.maker={name=n or ("Bosar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bosar najet: %s (spretnost: %d)",ShieldBossMaker.maker.name,s),"success") end; return true end
function ShieldBossMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ShieldBossMaker.build(id) local ok,e=ShieldBossMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ShieldBossMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ShieldBossMaker.getQualityBonus() local b=0; for _,bd in ipairs(ShieldBossMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ShieldBossMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ShieldBossMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ShieldBossMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ShieldBossMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ShieldBossMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ShieldBossMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ShieldBossMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ShieldBossMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ShieldBossMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ShieldBossMaker.buildings==0 then return false,"Potrebna bosna delavnica" end; if not ShieldBossMaker.maker then return false,"Potreben bosar" end; return true end
function ShieldBossMaker.make(pt,qty) qty=qty or 1; local ok,e=ShieldBossMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ShieldBossMaker.ironStock=ShieldBossMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ShieldBossMaker.bronzeStock=ShieldBossMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ShieldBossMaker.woodStock=ShieldBossMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ShieldBossMaker.leatherStock=ShieldBossMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ShieldBossMaker.silverStock=ShieldBossMaker.silverStock-d.silverCost*qty end; if d.goldCost then ShieldBossMaker.goldStock=ShieldBossMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ShieldBossMaker.jewelStock=ShieldBossMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ShieldBossMaker.pearlStock=ShieldBossMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ShieldBossMaker.maker then t=math.max(1,t-math.floor(ShieldBossMaker.maker.skill/13)) end; table.insert(ShieldBossMaker.activeMaking,{id="shieldboss_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ShieldBossMaker.completeMaking(m) local q=1.0+(ShieldBossMaker.getQualityBonus()/100); if ShieldBossMaker.maker then q=q+(ShieldBossMaker.maker.skill/140) end; q=math.min(2.5,q); ShieldBossMaker.productStock[m.productType]=(ShieldBossMaker.productStock[m.productType] or 0)+m.quantity; ShieldBossMaker.totalProducts=ShieldBossMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ShieldBossMaker.maker then ShieldBossMaker.maker.itemsMade=ShieldBossMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ShieldBossMaker.maker.skill=math.min(100,ShieldBossMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Boss izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shieldboss.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ShieldBossMaker.update(dt) if not _G.state then return end; ShieldBossMaker.dayTimer=ShieldBossMaker.dayTimer+dt; if ShieldBossMaker.dayTimer>=30 then ShieldBossMaker.dayTimer=0; for i=#ShieldBossMaker.activeMaking,1,-1 do local m=ShieldBossMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ShieldBossMaker.completeMaking(m); table.remove(ShieldBossMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ShieldBossMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ShieldBossMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ShieldBossMaker.getStats() return {ironStock=ShieldBossMaker.ironStock,bronzeStock=ShieldBossMaker.bronzeStock,woodStock=ShieldBossMaker.woodStock,leatherStock=ShieldBossMaker.leatherStock,silverStock=ShieldBossMaker.silverStock,goldStock=ShieldBossMaker.goldStock,jewelStock=ShieldBossMaker.jewelStock,pearlStock=ShieldBossMaker.pearlStock,productStock=ShieldBossMaker.productStock,numBuildings=#ShieldBossMaker.buildings,hasMaker=ShieldBossMaker.maker~=nil,makerName=ShieldBossMaker.maker and ShieldBossMaker.maker.name or "—",makerSkill=ShieldBossMaker.maker and ShieldBossMaker.maker.skill or 0,activeMaking=#ShieldBossMaker.activeMaking,totalProducts=ShieldBossMaker.totalProducts} end
return ShieldBossMaker
